import { createSlice, createAsyncThunk, configureStore } from '@reduxjs/toolkit';

export type User = { id: number; name: string };
export type UsersState = { items: User[]; status: 'idle' | 'loading' | 'success' | 'error' };

export const fetchUsers = createAsyncThunk<User[], void>(
  'users/fetch',
  async () => {
    const r = await fetch('/api/users');
    return r.json() as Promise<User[]>;
  },
);

const usersSlice = createSlice({
  name: 'users',
  initialState: { items: [], status: 'idle' } as UsersState,
  reducers: {},
  extraReducers: (builder) => {
    builder.addCase(fetchUsers.pending, (s) => {
      s.status = 'loading';
    });
    builder.addCase(fetchUsers.fulfilled, (s, a) => {
      s.status = 'success';
      s.items = a.payload;
    });
    builder.addCase(fetchUsers.rejected, (s) => {
      s.status = 'error';
    });
  },
});

export const store = configureStore({
  reducer: { users: usersSlice.reducer },
});

export type RootState = ReturnType<typeof store.getState>;
export type AppDispatch = typeof store.dispatch;
